   217→  }
   218→  
   219→  # 사용자 정의 함수
   220→  let funcs = env["functions"]
   221→  let func = funcs[name]
   222→  
   223→  if func == null {
   224→    return null  # 함수 정의 안 됨
   225→  }
   226→  
   227→  # 인자 평가
   228→  let args = []
   229→  let i = 0
   230→  while i < len(arg_nodes) {
   231→    args[i] = evalNode(arg_nodes[i], env)
   232→    i = i + 1
   233→  }
   234→  
   235→  # 새 환경 생성
   236→  let callEnv = {
   237→    "variables": {},
   238→    "functions": funcs,
   239→    "parent": env
   240→  }
   241→  
   242→  # 매개변수 바인딩
   243→  let params = func["params"]
   244→  i = 0
   245→  while i < len(params) {
   246→    setVariable(params[i], args[i], callEnv)
   247→    i = i + 1
   248→  }
   249→  
   250→  # 함수 본문 실행
   251→  return evalNode(func["body"], callEnv)
   252→}
   253→
   254→# ================================================================
   255→# Part 5: 메인 평가 함수 (AST 순회)
   256→# ================================================================
   257→
   258→fn evalNode(node: map, env: map): any {
   259→  if node == null {
   260→    return null
   261→  }
   262→  
   263→  let nodeType = node["type"]
   264→  
   265→  # 리터럴
   266→  if nodeType == "number" {
   267→    return node["value"]
   268→  } else if nodeType == "string" {
   269→    return node["value"]
   270→  } else if nodeType == "identifier" {
   271→    return getVariable(node["name"], env)
   272→  } else if nodeType == "boolean" {
   273→    return node["value"]
   274→  }
   275→  
   276→  # 이진 연산
   277→  else if nodeType == "binaryOp" {
   278→    let left = evalNode(node["left"], env)
   279→    let right = evalNode(node["right"], env)
   280→    return evalBinaryOp(left, right, node["operator"])
   281→  }
   282→  
   283→  # 단항 연산
   284→  else if nodeType == "unaryOp" {
   285→    let operand = evalNode(node["operand"], env)
   286→    return evalUnaryOp(operand, node["operator"])
   287→  }
   288→  
   289→  # 함수 호출
   290→  else if nodeType == "functionCall" {
   291→    return evalFunctionCall(node["name"], node["args"], env)
   292→  }
   293→  
   294→  # 변수 할당
   295→  else if nodeType == "assignment" {
   296→    let value = evalNode(node["value"], env)
   297→    return setVariable(node["variable"], value, env)
   298→  }
   299→  
   300→  # If 문
   301→  else if nodeType == "if" {
   302→    let cond = evalNode(node["condition"], env)
   303→    return evalIf(cond, node["thenBranch"], node["elseBranch"], env)
   304→  }
   305→  
   306→  # While 루프
   307→  else if nodeType == "while" {
   308→    return evalWhile(node["condition"], node["body"], env)
   309→  }
   310→  
   311→  # For 루프
   312→  else if nodeType == "for" {
   313→    return evalFor(node["variable"], node["start"], node["end"], node["body"], env)
   314→  }
   315→  
   316→  # 블록
   317→  else if nodeType == "block" {
   318→    return evalBlock(node["statements"], env)
   319→  }
   320→  
   321→  # 배열 리터럴
   322→  else if nodeType == "arrayLiteral" {
   323→    let elements = node["elements"]
   324→    let result = []
   325→    let i = 0
   326→    while i < len(elements) {
   327→      result[i] = evalNode(elements[i], env)
   328→      i = i + 1
   329→    }
   330→    return result
   331→  }
   332→  
   333→  # 배열 접근
   334→  else if nodeType == "arrayAccess" {
   335→    let array = evalNode(node["array"], env)
   336→    let index = evalNode(node["index"], env)
   337→    return array[index]
   338→  }
   339→  
   340→  # 함수 정의
   341→  else if nodeType == "functionDef" {
   342→    let params = node["params"]
   343→    let body = node["body"]
   344→    defineFunction(node["name"], params, body, env)
   345→    return null
   346→  }
   347→  
   348→  # 반환
   349→  else if nodeType == "return" {
   350→    # TODO: 예외로 처리할 수도 있음
   351→    return evalNode(node["value"], env)
   352→  }
   353→  
   354→  else {
   355→    return null
   356→  }
   357→}
